import React, { useState, useEffect } from "react";
import { NavLink } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { makeStyles, useTheme } from "@material-ui/core/styles";
import IconButton from "@material-ui/core/IconButton";
import moment from "moment";
import { TEXTS } from "../../../assets/languages/french";
import Dialog from "@material-ui/core/Dialog";
import GLOBALS from "../../../globals";
import Actions from "../../../redux/actions";

import Form from "../../../components/Form";
import Modal from "../../../components/Modal";
import Table from "../../../components/Table";
import Loader from "../../../components/Loader";
import { Images } from "../../../assets/Assets";
import Button from "../../../components/Button";
import Heading from "../../../components/Heading";
import SubHeading from "../../../components/SubHeading";
import SearchInput from "../../../components/SearchInput";
import uploadIcon from "../../../assets/images/upload.png";
import { isNull } from "lodash";

const useStyles = makeStyles((theme) => ({
  root: {
    padding: GLOBALS.Styles.pagePadding,
  },
  content: {
    overflow: "hidden",
    borderRadius: theme.shape.borderRadius,
    padding: GLOBALS.Styles.pageContentPadding,
    marginTop: GLOBALS.Styles.pageContentMargin,
    backgroundColor: theme.palette.secondary.main,
  },
}));

export default function Companies(props) {
  const {
    LIST_OF_COMPANIES,
    Add_COMPANY,
    NAME_OF_COMPANY,
    ACCESS_REQUEST_TO_ZONES,
    ACCESS_REQUEST_TO_STROGAEAREA,
    ACCEPT,
    REJECT,
  } = TEXTS;
  const theme = useTheme();
  const classes = useStyles();
  const dispatch = useDispatch();
  const store = useSelector((state) => state.auth);
  const adminStore = useSelector((state) => state.admin);

  const [companies, setCompanies] = useState([]);
  const [deleteModal, setDeleteModal] = useState(false);

  const [nameOfResponsible, setNameOfResponsible] = useState("");
  const [nameOfCompany, setNameOfCompany] = useState("");
  const [companyId, setCompanyId] = useState("");
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [storageAreaRequest, setStorageAreaRequest] = useState([]);

  useEffect(() => {
    getData();
    // eslint-disable-next-line
  }, []);

  const getData = async () => {
    try {
      const response = await GLOBALS.API({
        uri: `${GLOBALS.Constants.ADMIN_SITE_COMPANY}/${adminStore.site.siteId._id}`,
        token: store.token,
      });
      setCompanies(response.data);
      setLoading(false);
    } catch (err) {
      setLoading(false);
      dispatch(
        Actions.notistack.enqueueSnackbar(
          Actions.notistack.snackbar(err.message, "error"),
        ),
      );
    }
  };

  const filterCompany = async () => {
    try {
      const params = { siteId: adminStore.site.siteId._id };
      if (nameOfCompany.length !== 0) params["companyName"] = nameOfCompany;
      if (nameOfResponsible.length !== 0)
        params["responsibleName"] = nameOfResponsible;

      const response = await GLOBALS.API({
        uri: `${GLOBALS.Constants.ADMIN_SITE_COMPANY_FILTER}`,
        token: store.token,
        method: "POST",
        body: JSON.stringify(params),
      });
      const companies = response.data.companies.filter((x) => {
        return x.companyId !== null || undefined;
      });
      setCompanies(companies);
    } catch (err) {
      dispatch(
        Actions.notistack.enqueueSnackbar(
          Actions.notistack.snackbar(err.message, "error"),
        ),
      );
    }
  };
  const handleClickOpen = async () => {
    await fetchAccessToZone();
    setOpen(true);
  };
  const fetchAccessToZone = async () => {
    try {
      const response = await GLOBALS.API({
        uri: `${GLOBALS.Constants.GET_SITE_STORAGE_AREA}/${adminStore.site.siteId._id}`,
        token: store.token,
      });
      setStorageAreaRequest(response.data);
    } catch (err) {
      dispatch(
        Actions.notistack.enqueueSnackbar(
          Actions.notistack.snackbar(err.message, "error"),
        ),
      );
    }
  };
  const onAccept = async (id) => {
    try {
      await GLOBALS.API({
        uri: `${GLOBALS.Constants.ACCEPT_SITE_STORAGE_AREA}/${id}`,
        token: store.token,
      });
      dispatch(
        Actions.notistack.enqueueSnackbar(
          Actions.notistack.snackbar(
            GLOBALS.I18n.t("storageAreaAccept"),
            "success",
          ),
        ),
      );
      await fetchAccessToZone();
    } catch (err) {
      dispatch(
        Actions.notistack.enqueueSnackbar(
          Actions.notistack.snackbar(err.message, "error"),
        ),
      );
    }
  };
  const onReject = async (id) => {
    try {
      await GLOBALS.API({
        uri: `${GLOBALS.Constants.REJECT_SITE_STORAGE_AREA}/${id}`,
        token: store.token,
      });

      dispatch(
        Actions.notistack.enqueueSnackbar(
          Actions.notistack.snackbar(
            GLOBALS.I18n.t("storageAreaRequestReject"),
            "success",
          ),
        ),
      );
      await fetchAccessToZone();
    } catch (err) {
      dispatch(
        Actions.notistack.enqueueSnackbar(
          Actions.notistack.snackbar(err.message, "error"),
        ),
      );
    }
  };

  //   Delete company
  const handleDelete = async (id) => {
    try {
      setLoading(true);
      await GLOBALS.API({
        uri: `${GLOBALS.Constants.ADMIN_SITE_COMPANY_DELETE}/${adminStore.site.siteId._id}/${id}`,
        token: store.token,
        method: "DELETE",
      });
      setLoading(false);
      setDeleteModal(false);
      setCompanyId("");
      getData();
    } catch (err) {
      setLoading(false);
      setCompanyId("");
      setDeleteModal(false);
      dispatch(
        Actions.notistack.enqueueSnackbar(
          Actions.notistack.snackbar(err.message, "error"),
        ),
      );
    }
  };

  const requestRows = storageAreaRequest.map((item) => {
    return [
      item.companyId.name,
      item.requestDate ? moment(item.requestDate).format("DD/MM/yyyy") : " ",
      item.storageAreaId.name,
      <div>
        <Button
          onClick={() => onAccept(item._id)}
          type="submit"
          text={ACCEPT}
          fullWidth={false}
        />{" "}
        <Button
          type="submit"
          color={theme.palette.error.main}
          text={REJECT}
          fullWidth={false}
          onClick={() => onReject(item._id)}
        />
      </div>,
    ];
  });

  const rows = companies.map((item, index) => {
    return [
      <img src={Images.site} alt="Icon" />,
      item.companyId.name,
      item.parentCompanyId ? item.parentCompanyId.name : "N/A",
      item.companyId.incharge !== undefined
        ? item.companyId.incharge.firstName && item.companyId.incharge.lastName
          ? item.companyId.incharge.firstName +
            " " +
            item.companyId.incharge.lastName
          : "-"
        : "N/A",
      item.companyId.incharge !== undefined
        ? item.companyId.incharge.phone
        : "N/A",
      item.companyId.incharge !== undefined
        ? item.companyId.incharge.email
          ? item.companyId.incharge.email
          : "-"
        : "N/A",

      <div>
        <>
          <div>
            <IconButton style={{ padding: "6px" }} onClick={() => {}}>
              <NavLink
                to={{
                  pathname: `/companies/user-list/${item.companyId._id}`,
                  id: item.companyId._id,
                }}
              >
                <img
                  src={Images.comapnies}
                  style={{ width: 18, height: 17 }}
                  alt="Icon"
                />
              </NavLink>
            </IconButton>
            <IconButton style={{ padding: "6px" }} onClick={() => {}}>
              <NavLink to={`/companies/edit/${item.companyId._id}`}>
                <img
                  src={Images.pencil}
                  style={{ width: 18, height: 17 }}
                  alt="Icon"
                />
              </NavLink>
            </IconButton>
            <IconButton style={{ padding: "6px" }} onClick={() => {}}>
              <NavLink
                to={{
                  pathname: "/",
                  companyId: item.companyId._id,
                }}
              >
                <img
                  src={Images.calender}
                  style={{ width: 18, height: 17 }}
                  alt="Icon"
                />
              </NavLink>
            </IconButton>
            <IconButton
              style={{ padding: "6px", color: "#1890ff" }}
              onClick={() => {}}
            >
              <NavLink
                to={{
                  pathname: `/incidents`,
                  search: `?companyId=${item.companyId._id}`,
                }}
              >
                <img
                  src={Images.incidents}
                  style={{ width: 18, height: 17 }}
                  alt="Icon"
                />
              </NavLink>
            </IconButton>
            {item.companyId?.type === "NOCLIENTS" && (
              <IconButton
                style={{ padding: "6px", opacity: "0.7" }}
                onClick={() => handleDeleteModal({ id: item.companyId._id })}
              >
                <img
                  src={Images.trash}
                  style={{ width: 18, height: 17 }}
                  alt="Icon"
                />
              </IconButton>
            )}
          </div>
        </>
      </div>,
    ];
  });

  //   This function will open and close confirmation popup to delete a company
  const handleDeleteModal = ({ id }) => {
    setDeleteModal(id ? true : false);
    setCompanyId(id || "");
  };

  return (
    <>
      {/* Confirmation popup component to delete company */}
      <DeleteModal
        open={deleteModal}
        handleDeleteModal={handleDeleteModal}
        id={companyId}
        handleDelete={handleDelete}
      />
      <div className={classes.root}>
        <Form.Row alignItems="center" className="pr-3">
          <Heading primary={LIST_OF_COMPANIES} noWrap noMargin />
          <div>
            <Form.Row alignItems="center" noMargin>
              <SubHeading
                bold
                noMargin
                disableMargin
                primary={`Total : ${companies.length} Entreprise`}
              />
              <Button
                fullWidth={false}
                component={NavLink}
                text={Add_COMPANY}
                to={"/companies/add"}
                style={{ marginLeft: "20px" }}
              />
            </Form.Row>
          </div>
        </Form.Row>
        <Form.Row noMargin className="pr-3">
          <Form.Row style={{ justifyContent: "flex-start" }} noMargin>
            <SearchInput
              placeholder="Nom Of Responsible"
              value={nameOfResponsible}
              onClick={filterCompany}
              onChange={(event) => {
                setNameOfResponsible(event.target.value);
              }}
            />
            <SearchInput
              style={{ marginLeft: "20px" }}
              placeholder={NAME_OF_COMPANY}
              value={nameOfCompany}
              onClick={filterCompany}
              onChange={(event) => {
                setNameOfCompany(event.target.value);
              }}
            />
          </Form.Row>
          <Button
            noWrap
            fullWidth={true}
            onClick={handleClickOpen}
            style={{ width: "330px" }}
            text={ACCESS_REQUEST_TO_ZONES}
          />
        </Form.Row>
        <div className={classes.content}>
          {loading ? (
            <Loader.Progress />
          ) : (
            <Table headers={GLOBALS.Data.companies.headings} rows={rows} />
          )}
        </div>
      </div>

      <Modal
        title={ACCESS_REQUEST_TO_STROGAEAREA}
        open={open}
        onClose={() => setOpen(false)}
        body={
          <div className={classes.content}>
            <Table
              headers={GLOBALS.Data.accessToStorageArea.headings}
              rows={requestRows}
            />
          </div>
        }
      />
    </>
  );
}

// Confirmation popup to delete company
const DeleteModal = (props) => {
  return (
    <Dialog maxWidth={"md"} open={props.open} onClose={props.handleDeleteModal}>
      <div className="" style={{ padding: "15px 20px" }}>
        <h3>Etes-vous sûr que vous voulez supprimer?</h3>
        <div style={{ padding: "20px", textAlign: "right" }}>
          <button
            onClick={props.handleDeleteModal}
            style={{
              border: "none",
              borderRadius: "10px",
              padding: "10px 25px",
              marginRight: "15px",
              fontSize: "18px",
              cursor: "pointer",
            }}
          >
            Annuler
          </button>
          <button
            onClick={() => props.handleDelete(props.id)}
            style={{
              backgroundColor: "#DBB20A",
              border: "none",
              borderRadius: "10px",
              padding: "10px 25px",
              fontSize: "18px",
              cursor: "pointer",
            }}
          >
            Supprimer
          </button>
        </div>
      </div>
    </Dialog>
  );
};
